<?php declare(strict_types=1); require_once __DIR__.'/../includes/auth.php'; requireAdmin(); $pdo=db(); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $client=(int)($_POST['client_id']??0); $message=trim((string)($_POST['message']??'')); if($client&&$message){$pdo->prepare('INSERT INTO sms_messages(client_id,message) VALUES(?,?)')->execute([$client,$message]);$msg='Mensagem salva.';}} $clients=$pdo->query('SELECT id,username FROM clients WHERE status="active" ORDER BY username')->fetchAll(); $pageTitle='SMS — ATX Panel'; require __DIR__.'/includes/header.php'; ?>
<h1 class="page-title">SMS</h1><p class="page-subtitle">Mensagem específica por cliente.</p><div class="panel"><p><?=$msg?></p><form method="post"><select name="client_id" required><option value="">Cliente</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['username'])?></option><?php endforeach;?></select><br><textarea name="message" placeholder="Mensagem..." required style="width:100%;min-height:120px"></textarea><br><button class="btn">Salvar</button></form></div><?php require __DIR__.'/includes/footer.php'; ?>
